record.field:
{"type": "object", "properties": {
            "model": {"type": "string", "description": "Technical model name."},
            "domain": {"type": "array", "description": "Odoo domain as array of [field, operator, value] triples."},
            "fields": {"type": "array", "items": {"type": "string"}, "description": "Field names to return."},
            "limit": {"type": "integer", "description": "Max records (default 25, max 200)."},
            "order": {"type": "string", "description": "Sort expression e.g. 'date_order desc, id'."},
            "offset": {"type": "integer", "description": "Skip first N records."}
        }, "required": ["model"]}

{"type": "object", "properties": {
            "model": {"type": "string"},
            "groupby": {"description": "Field name or list of field names to group by.", "oneOf": [{"type": "string"}, {"type": "array", "items": {"type": "string"}}]},
            "aggregate_fields": {"type": "array", "items": {"type": "string"}, "description": "List of 'field:operator' strings, or ['__count']."},
            "domain": {"type": "array"},
            "limit": {"type": "integer"}
        }, "required": ["model", "groupby"]}

{"type": "object", "properties": {
            "model": {"type": "string"},
            "values_list": {"description": "Object or array of objects with target field values.", "oneOf": [{"type": "object"}, {"type": "array"}]},
            "return_fields": {"type": "array", "items": {"type": "string"}},
            "dry_run": {"type": "boolean"}
        }, "required": ["model", "values_list"]}

{"type": "object", "properties": {
            "kpi_code": {"type": "string", "description": "KPI code from list_kpis."},
            "date_from": {"type": "string", "description": "Optional ISO date (YYYY-MM-DD) to filter create_date from."},
            "date_to": {"type": "string", "description": "Optional ISO date to filter create_date to."},
            "extra_domain": {"type": "array", "description": "Optional additional domain triples."}
        }, "required": ["kpi_code"]}

{"type": "object", "properties": {
            "forecast_type": {"type": "string", "enum": ["revenue", "cashflow", "pipeline_conversion", "ar_collections", "inventory_demand", "custom"], "description": "What to forecast."},
            "periods": {"type": "integer", "description": "Number of future periods (default 3, max 12)."},
            "period_unit": {"type": "string", "enum": ["month", "quarter", "year"]}
        }, "required": []}

{"type": "object", "properties": {
            "scenario_type": {"type": "string", "enum": ["price_change", "volume_change", "cost_change", "customer_churn", "headcount_change", "payment_terms_change", "custom"]},
            "change_pct": {"type": "number", "description": "Magnitude of change as a percentage, e.g. 10 for 10%."},
            "direction": {"type": "string", "enum": ["increase", "decrease"]},
            "extra_params": {"type": "object", "description": "Optional scenario-type-specific extra parameters."}
        }, "required": ["scenario_type", "change_pct"]}

{"type": "object", "properties": {
            "metric_categories": {"type": "array", "items": {"type": "string"}, "description": "List of metric categories to compare. Default: revenue, margin, ar_days, inventory_turns."},
            "country_code": {"type": "string"},
            "industry_code": {"type": "string"}
        }, "required": []}

{"type": "object", "properties": {
            "attachment_id": {"type": "integer"},
            "sheet_name": {"type": "string", "description": "Optional sheet/table name for Excel or multi-table files."},
            "max_rows": {"type": "integer", "description": "Maximum number of extracted rows to return (default 100)."}
        }, "required": ["attachment_id"]}

{"type": "object", "properties": {
            "model": {"type": "string"},
            "attachment_id": {"type": "integer"},
            "field_map": {"type": "object", "description": "Map of target Odoo field => source column key/index from extracted rows."},
            "mode": {"type": "string", "enum": ["create", "upsert"]},
            "key_field": {"type": "string", "description": "Required for upsert mode. Target field used to find existing records."},
            "sheet_name": {"type": "string"},
            "max_rows": {"type": "integer"},
            "dry_run": {"type": "boolean", "description": "If true, validate/preview import without writing records."}
        }, "required": ["model", "attachment_id", "field_map"]}

{"type": "object", "properties": {
            "text": {"type": "string", "description": "Reminder text (max ~120 chars)."},
            "due_datetime": {"type": "string", "description": "ISO datetime in UTC, e.g. '2026-05-25 09:00:00'."}
        }, "required": ["text"]}

{"type": "object", "properties": {
            "model": {"type": "string"},
            "record_id": {"type": "integer"},
            "summary": {"type": "string", "description": "Short activity title."},
            "note": {"type": "string", "description": "Detailed activity note."},
            "due_date": {"type": "string", "description": "ISO date YYYY-MM-DD."}
        }, "required": ["model", "record_id", "summary"]}
